SELECT COUNT(*)
FROM edu.exam_matrix_row_learning_level_counts
WHERE custom_learning_level_id = #{id}

SELECT COUNT(*)
FROM edu.exam_matrix_row_learning_level_counts count_record
WHERE count_record.custom_learning_level_id = #{id}
  AND NOT EXISTS (
    SELECT 1
    FROM edu.exam_matrix_row_learning_outcomes row_outcome
    WHERE row_outcome.exam_matrix_row_id = count_record.exam_matrix_row_id
      AND row_outcome.learning_outcome_id IN
      #{outcomeId}
  )

